    vector<int> arr = {3, 2, 5, 1, 8, 9};
    vector<int> query1 = {2, 5, 2};
    kth_elem(arr, query1);
    vector<int> query2 = {1, 6, 4};
    kth_elem(arr, query2);
      return 0;
}

